<?php
namespace App\Form\Admin\Clients;
use App\Application\Clients\ClientBranchAddressData; use App\Entity\Clients\DeliveryZone; use Symfony\Bridge\Doctrine\Form\Type\EntityType; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,ChoiceType,HiddenType,MoneyType,TextareaType,TextType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver;
final class ClientBranchAddressEntryType extends AbstractType { public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('id',HiddenType::class)->add('type',ChoiceType::class,['label'=>'Uso','choices'=>['Comercial'=>'COMMERCIAL','Fiscal'=>'FISCAL','Entrega'=>'DELIVERY']])->add('street',TextType::class,['label'=>'Calle'])->add('exteriorNumber',TextType::class,['label'=>'Núm. exterior'])->add('interiorNumber',TextType::class,['label'=>'Núm. interior','required'=>false])->add('neighborhood',TextType::class,['label'=>'Colonia','required'=>false])->add('postalCode',TextType::class,['label'=>'Código postal'])->add('city',TextType::class,['label'=>'Municipio / ciudad'])->add('state',TextType::class,['label'=>'Estado','required'=>false])->add('countryCode',TextType::class,['label'=>'País'])->add('deliveryZone',EntityType::class,['class'=>DeliveryZone::class,'choice_label'=>'name','placeholder'=>'Sin zona de entrega','required'=>false])->add('deliveryCost',MoneyType::class,['label'=>'Costo de entrega','currency'=>'MXN','required'=>false])->add('notes',TextareaType::class,['label'=>'Referencias','required'=>false,'attr'=>['rows'=>2]])->add('isDefault',CheckboxType::class,['label'=>'Predeterminado','required'=>false]);} public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>ClientBranchAddressData::class]);}}
